from pathlib import Path
import json,sys
ROOT=Path(__file__).resolve().parents[1]
def check(ok,label):
    if not ok:
        print('FAIL - '+label);sys.exit(1)
    print('PASS - '+label)
main=(ROOT/'wordpress/sustainable-catalyst-workspace/sustainable-catalyst-workspace.php').read_text()
php=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace.php').read_text()
reg=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace-registry.php').read_text()
js=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/workspace-v0.30.0.js').read_text()
helper=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-public-beta-v1.js').read_text()
css=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/css/workspace-v0.30.0.css').read_text()
manifest=json.loads((ROOT/'release-manifest-v0.30.0.json').read_text())
record=json.loads((ROOT/'registry/workspace-product-record-v0.30.0.json').read_text())
check('Version: 0.30.0' in main and "define('SC_WORKSPACE_VERSION', '0.30.0')" in main,'plugin/runtime version')
check(manifest['version']=='0.30.0' and manifest['previous_version']=='0.29.0','manifest release lineage')
check(manifest['release_name']=='Public Beta & Product Readiness','release name')
check(manifest['storage_schema_version']==27 and manifest['project_schema']=='sc-workspace-project/12.0','storage 27 / project 12.0')
check(not manifest['schema_migration_required'] and manifest['migration']['storage_from']==27 and manifest['migration']['storage_to']==27,'schema-stable release')
check(manifest['migration']['project_schema_unchanged'] and manifest['migration']['project_schema_from']=='sc-workspace-project/12.0','project schema unchanged')
check("'/public-beta-contract'" in php and 'public function public_beta_contract()' in php,'Public Beta REST contract')
check(manifest['public_beta_schema']=='sc-workspace-public-beta-readiness/1.0','Public Beta readiness schema')
check(manifest['public_beta']['quick_starts']==['research-investigation','analytical-assessment','decision-case','publication-preparation'],'four guided quick starts')
check(manifest['public_beta']['start_view'] and "let workspaceView = 'start'" in js,'Start-first experience')
check('data-scw-beta-new' in php and 'data-scw-beta-continue' in php and 'startBetaGuidedProject' in js,'first-project actions')
check(all(x in helper for x in ['localStorage','sessionStorage','webCryptoSha256','fileApi','postMessage']),'runtime capability checks')
check("['ArrowLeft','ArrowRight','Home','End']" in js and "setAttribute('aria-current', 'page')" in js,'keyboard Workspace navigation')
check(':focus-visible' in css and 'prefers-reduced-motion:reduce' in css and 'forced-colors:active' in css,'accessibility visual hardening')
check(manifest['public_beta']['guest_workspace_supported'] and not manifest['public_beta']['login_wall'],'guest Workspace retained')
check(not manifest['public_beta']['automatic_cloud_upload'] and not manifest['public_beta']['background_sync'],'no automatic cloud/background sync')
check(not manifest['public_beta']['automatic_telemetry'] and not manifest['public_beta']['hidden_readiness_score'],'no telemetry or hidden readiness score')
check(not manifest['public_beta']['automatic_lifecycle_advance'],'human lifecycle boundary retained')
check(manifest['canonical_library_path']=='/knowledge-libraries/' and '/knowledge-libraries/' in php,'canonical Knowledge Library route')
check(record['public_version']=='0.30.0' and record['previous_version']=='0.29.0','registry record lineage')
check("BACKUP_KEY = 'sc_workspace_registry_backup_v0300'" in reg and "PENDING_KEY = 'sc_workspace_registry_pending_v0300'" in reg and 'LEGACY_PENDING_KEY_V0290' in reg,'registry pending/backup lineage')
check((ROOT/'history/release-manifest-v0.29.0.json').exists() and (ROOT/'history/workspace-product-record-v0.29.0.json').exists(),'v0.29.0 history preserved')
for f in ('sc-workspace-public-beta-readiness-v1.schema.json','sc-workspace-project-v12.schema.json','sc-workspace-project-lifecycle-v1.schema.json'):
    json.loads((ROOT/'schemas'/f).read_text())
check(True,'schema JSON')
print('VALIDATION PASSED: Sustainable Catalyst Workspace v0.30.0 — Public Beta & Product Readiness')
